changeSet.sql:
CREATE OR REPLACE FUNCTION enforce_consent_decision_append_only()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'UPDATE'
       AND OLD.account_id IS NOT NULL AND NEW.account_id IS NULL
       AND OLD.id = NEW.id
       AND OLD.purpose = NEW.purpose
       AND OLD.granted = NEW.granted
       AND OLD.mechanism = NEW.mechanism
       AND OLD.notice_version = NEW.notice_version
       AND OLD.notice_sha256 = NEW.notice_sha256
       AND OLD.occurred_at = NEW.occurred_at THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'consent_decision is append-only';
END;
$$;
CREATE TRIGGER trg_consent_decision_append_only
    BEFORE UPDATE OR DELETE ON consent_decision
    FOR EACH ROW EXECUTE FUNCTION enforce_consent_decision_append_only();

CREATE OR REPLACE FUNCTION enforce_consent_notice_immutable()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'consent_notice is immutable';
END;
$$;
CREATE TRIGGER trg_consent_notice_immutable
    BEFORE UPDATE OR DELETE ON consent_notice
    FOR EACH ROW EXECUTE FUNCTION enforce_consent_notice_immutable();

rollback.sql:
DROP TRIGGER IF EXISTS trg_consent_decision_append_only ON consent_decision;
DROP FUNCTION IF EXISTS enforce_consent_decision_append_only();
DROP TRIGGER IF EXISTS trg_consent_notice_immutable ON consent_notice;
DROP FUNCTION IF EXISTS enforce_consent_notice_immutable();
